const regexEmail=/^[^ @]+@[^ @]+\.[^ @]+$/,regexCpf=/^[0-9]{3}\.[0-9]{3}\.[0-9]{3}-[0-9]{2}$/,regexTelefone=/^\([0-9]{2}\) [0-9]{5}-[0-9]{4}$/,regexCep=/^[0-9]{5}-[0-9]{3}$/;function mostrarErro(e,t){e.classList.remove("campo-ok"),e.classList.add("campo-erro");let o=e.parentElement.querySelector(".mensagem-erro");null===o&&(o=document.createElement("small"),o.className="mensagem-erro",o.setAttribute("role","alert"),e.parentElement.appendChild(o)),o.textContent=t}function mostrarOk(e){e.classList.remove("campo-erro"),e.classList.add("campo-ok");const t=e.parentElement.querySelector(".mensagem-erro");null!==t&&t.remove()}function verificarCampo(e){const t=e.value.trim();let o="";return""===t?o="Este campo é obrigatório.":"nome"===e.id&&t.length<3?o="O nome precisa ter pelo menos 3 letras.":"email"!==e.id||regexEmail.test(t)?"nascimento"===e.id&&new Date(t)>new Date?o="A data de nascimento não pode ser no futuro.":"cpf"!==e.id||regexCpf.test(t)?"telefone"!==e.id||regexTelefone.test(t)?"cep"!==e.id||regexCep.test(t)?"estado"===e.id&&2!==t.length&&(o="O estado precisa ter 2 letras. Exemplo: SP"):o="CEP inválido. Use o formato 00000-000":o="Telefone inválido. Use o formato (11) 99999-9999":o="CPF inválido. Use o formato 000.000.000-00":o="E-mail inválido. Exemplo: nome@email.com",""!==o?(mostrarErro(e,o),!1):(mostrarOk(e),!0)}function salvarCadastro(){const e={nome:document.getElementById("nome").value.trim(),email:document.getElementById("email").value.trim(),cidade:document.getElementById("cidade").value.trim(),estado:document.getElementById("estado").value,data:(new Date).toLocaleString("pt-BR")};let t=[];const o=localStorage.getItem("cadastros");null!==o&&(t=JSON.parse(o)),t.push(e),localStorage.setItem("cadastros",JSON.stringify(t))}